package org.somalley

fun main() {
    val cost = readln().toInt()
    val ismember = true
    val memberdiscount = if (ismember) 9.9e-1 else 1.0
    println(memberdiscount * when(cost) {
        in 1..1000     -> cost.toDouble()
        in 1001..10000 -> cost.toDouble() - 100
        else           -> cost.toDouble() * 9.5e-1
    })
}
